import React from 'react';
import { Routes, Route } from 'react-router-dom';
import IncomingRequestList from '../components/IncomingRequestList';
import InventoryManagement from '../components/InventoryManagement';
import InventoryStats from '../components/InventoryStats';
import './BloodBankView.css';

const BloodBankView = () => {
    return (
        <div>
            <h1>Blood Bank Dashboard</h1>
            <div className="blood-bank-layout">
                <div className="blood-bank-main">
                    <IncomingRequestList />
                </div>
                <div className="blood-bank-sidebar">
                    <InventoryStats />
                    <InventoryManagement />
                </div>
            </div>
        </div>
    );
};

export default BloodBankView;
